#!/bin/bash
# Manifest checks: render what reaches the cluster (ArgoCD Applications, Helm
# charts with their airgap values, directories applied by scripts) and
# validate every object with kubeconform, strict (unknown fields rejected).
#
# Schemas:
#   - Kubernetes 1.28.5 (k3s_version in 04-ansible/group_vars/all.yml);
#   - CRDs rendered from the charts of this repository (.cache/schemas);
#   - CRDs whose charts or manifests are not in git (CNPG 1.30.1, Barman Cloud
#     plugin v0.16.0, Traefik chart 39.0.1): 03-airgap-zone/tests/manifests/schemas,
#     regenerated by update-schemas.sh;
#   - anything else (MetalLB): the datreeio CRDs catalog, pinned.
# CustomResourceDefinitions themselves are not validated (upstream content).
set -euo pipefail
cd "$(dirname "$0")/../.."
. scripts/check/images.sh
T=03-airgap-zone/tests/manifests
K8S_VERSION=1.28.5
K8S_SCHEMAS=47163ead3738a996c3e30be9691bb37b8071d9d3   # yannh/kubernetes-json-schema, 2026-10-29
CRD_CATALOG=3eb90d47aba8d61919d4419dd38301536e32a94b   # datreeio/CRDs-catalog, 2026-10-25

rm -rf .cache/rendered .cache/schemas
mkdir -p .cache
echo "== render"
HELM="docker run --rm -v $PWD:$PWD -w $PWD $HELM_IMAGE" python3 "$T/render.py" . .cache/rendered
python3 "$T/crd2schema.py" .cache/schemas .cache/rendered/*.yaml

echo "== kubeconform"
docker run --rm -v "$PWD:$PWD" -w "$PWD" "$KUBECONFORM_IMAGE" \
  -strict -summary -kubernetes-version "$K8S_VERSION" -skip CustomResourceDefinition \
  -schema-location "https://raw.githubusercontent.com/yannh/kubernetes-json-schema/$K8S_SCHEMAS/{{.NormalizedKubernetesVersion}}-standalone{{.StrictSuffix}}/{{.ResourceKind}}{{.KindSuffix}}.json" \
  -schema-location "$PWD/.cache/schemas/{{.Group}}/{{.ResourceKind}}_{{.ResourceAPIVersion}}.json" \
  -schema-location "$PWD/$T/schemas/{{.Group}}/{{.ResourceKind}}_{{.ResourceAPIVersion}}.json" \
  -schema-location "https://raw.githubusercontent.com/datreeio/CRDs-catalog/$CRD_CATALOG/{{.Group}}/{{.ResourceKind}}_{{.ResourceAPIVersion}}.json" \
  .cache/rendered/
